  "identity": {
    "name": "Levante",
    "tagline": "Small plates. Big table. Every time.",
    "one_line_description": "Levante is a Mediterranean mezze bar offering a curated, shareable dining experience rooted in the flavors of the eastern Mediterranean.",
    "domain": "restaurant",
    "subdomain": "Mediterranean mezze bar",
    "voice": [
      "warm",
      "precise",
      "inviting",
      "confident"
    ],
    "target_audience": "Urban food-forward diners aged 28\u201350 who value quality ingredients, communal dining, and a refined yet relaxed atmosphere for both weeknight meals and special occasions."
  },
  "pages": [
    {
      "slug": "home",
      "title": "Home",
      "role": "landing",
      "goal": "Immediately communicate Levante's identity as a refined Mediterranean mezze bar, establish appetite appeal, and drive visitors toward the menu and reservations.",
      "meta_description": "Levante is a Mediterranean mezze bar serving shareable small plates inspired by the flavors of the eastern Mediterranean. Explore our menu and reserve your table.",
