        {
          "id": "home-section-1",
          "type": "hero",
          "intent": "Make a strong first impression that captures the communal, abundant spirit of mezze dining and prompts visitors to explore the menu or book a table.",
          "eyebrow": "Mediterranean Mezze Bar",
          "headline": "Every Meal Deserves a Longer Table",
          "subheadline": "Shareable plates, bold flavors, and a dining ritual worth repeating \u2014 welcome to Levante.",
          "body": null,
          "items": [],
          "ctas": [
            {
              "label": "View the Menu",
              "target_page": "menu"
            },
            {
              "label": "Reserve a Table",
              "target_page": "contact"
            }
          ],
          "asset_ideas": [
