              "metadata": {}
            },
            {
              "title": "Seasonal Without Exception",
              "description": "The menu shifts quarterly. Some favorites return. Others make way for what the season demands.",
              "metadata": {}
            },
            {
              "title": "Hospitality as Practice",
              "description": "In the eastern Mediterranean, hospitality is not a service standard \u2014 it is a cultural obligation. We hold that standard.",
              "metadata": {}
            },
            {
              "title": "The Long Lunch Principle",
              "description": "We design the experience so that no one feels rushed. The table is yours for the evening.",
              "metadata": {}
            }
          ],
          "ctas": [],
          "asset_ideas": []
        },
